"""Cross-role offboarding controls for Build 07."""
from datetime import date, datetime, timezone
import re
from onboarding_sim.database import transaction
from onboarding_sim.services.workflows import append_audit


def _now():
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _next_id(conn, table, column, prefix):
    # Avoid collisions with IDs generated by other services using different prefixes.
    n = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
    while True:
        candidate = f"{prefix}{n + 1:08d}"
        if not conn.execute(f"SELECT 1 FROM {table} WHERE {column}=?", (candidate,)).fetchone():
            return candidate
        n += 1


def _audit(conn, actor, action, entity_type, entity_id, old, new, reason, related_case_id=None):
    append_audit(conn, _next_id(conn, "audit_events", "event_id", "EVT-OFF-"),
                 actor["user_id"], actor["app_role"], action, entity_type, entity_id,
                 old, new, reason, _now())


def list_cases(conn, status=None):
    sql = """SELECT o.*,e.full_name,e.work_email,e.department_id,e.manager_id
             FROM offboarding_cases o JOIN employees e ON e.employee_id=o.employee_id"""
    params = ()
    if status:
        sql += " WHERE o.status=?"
        params = (status,)
    return conn.execute(sql + " ORDER BY o.is_urgent DESC,o.last_working_day,o.offboarding_id", params).fetchall()


def case_detail(conn, offboarding_id):
    case = conn.execute(
        """SELECT o.*,e.full_name,e.work_email,e.employment_status,e.manager_id
           FROM offboarding_cases o JOIN employees e ON e.employee_id=o.employee_id
           WHERE o.offboarding_id=?""", (offboarding_id,)
    ).fetchone()
    if not case:
        raise ValueError("Offboarding case not found")
    tasks = conn.execute(
        "SELECT * FROM tasks WHERE case_id=? AND case_type='OFFBOARDING' ORDER BY due_date,task_id",
        (offboarding_id,)
    ).fetchall()
    grants = conn.execute(
        """SELECT g.grant_id,g.status,a.system_name,a.privilege_level
           FROM access_grants g JOIN access_roles a ON a.access_role_id=g.access_role_id
           WHERE g.employee_id=? ORDER BY g.grant_id""", (case["employee_id"],)
    ).fetchall()
    assets = conn.execute(
        """SELECT aa.assignment_id,aa.status,a.asset_type,a.model,a.serial_number
           FROM asset_assignments aa JOIN assets a ON a.asset_id=aa.asset_id
           WHERE aa.employee_id=? AND aa.status NOT IN ('RECOVERED','CANCELLED')
           ORDER BY aa.assigned_date""", (case["employee_id"],)
    ).fetchall()
    return case, tasks, grants, assets


def complete_owned_task(conn, task_id, owner_team, actor, reason):
    reason = (reason or "").strip()
    if not reason:
        raise ValueError("A completion note is required")
    row = conn.execute(
        "SELECT * FROM tasks WHERE task_id=? AND case_type='OFFBOARDING' AND owner_team=?",
        (task_id, owner_team)
    ).fetchone()
    if not row:
        raise ValueError("Offboarding task not found for your team")
    if row["status"] == "DONE":
        raise ValueError("Task is already completed")
    if row["status"] == "CANCELLED":
        raise ValueError("Cancelled tasks cannot be completed")
    with transaction(conn):
        conn.execute("UPDATE tasks SET status='DONE',completed_date=? WHERE task_id=?",
                     (date.today().isoformat(), task_id))
        _audit(conn, actor, "OFFBOARDING_TASK_COMPLETED", "Task", task_id,
               row["status"], "DONE", reason, row["case_id"])
        conn.execute(
            """INSERT INTO workflow_decisions(decision_id,case_id,decision_type,rule_id,inputs_ref,outcome,reason,created_at)
               VALUES(?,?,?,?,?,?,?,?)""",
            (_next_id(conn, "workflow_decisions", "decision_id", "DEC-OFF-"),
             row["case_id"], "TASK_COMPLETION", "OFFBOARDING_OWNER_COMPLETION",
             task_id, "COMPLETED", reason, _now())
        )
    return row["case_id"]


def close_case(conn, offboarding_id, actor, reason):
    reason = (reason or "").strip()
    if not reason:
        raise ValueError("Closure note is required")
    case, tasks, grants, assets = case_detail(conn, offboarding_id)
    if case["status"] == "CLOSED":
        raise ValueError("Offboarding case is already closed")
    open_tasks = [t for t in tasks if t["status"] not in ("DONE", "CANCELLED")]
    active_grants = [g for g in grants if g["status"] == "GRANTED"]
    active_assets = list(assets)
    blockers = []
    if open_tasks:
        blockers.append(f"{len(open_tasks)} offboarding task(s) remain open")
    if active_grants:
        blockers.append(f"{len(active_grants)} active access grant(s) remain")
    if active_assets:
        blockers.append(f"{len(active_assets)} asset assignment(s) remain unrecovered")
    if blockers:
        raise ValueError("Cannot close case: " + "; ".join(blockers))
    with transaction(conn):
        conn.execute("UPDATE offboarding_cases SET status='CLOSED',completed_date=? WHERE offboarding_id=?",
                     (date.today().isoformat(), offboarding_id))
        _audit(conn, actor, "OFFBOARDING_CASE_CLOSED", "OffboardingCase", offboarding_id,
               case["status"], "CLOSED", reason, offboarding_id)
        conn.execute(
            """INSERT INTO notifications(recipient_role,type,entity_type,entity_id,message,created_at)
               VALUES('HR','OFFBOARDING_CLOSED','OffboardingCase',?,?,?)""",
            (offboarding_id, f"Offboarding completed for {case['full_name']}.", _now())
        )
    return True
